import React, { useState } from 'react';

const productosData = [
  { id: 1, nombre: 'Casco Integral Sport', precio: 350000, categoria: 'Seguridad', imagen: '🪖' },
  { id: 2, nombre: 'Aceite Motor 4T 10W40', precio: 45000, categoria: 'Mantenimiento', imagen: '🛢️' },
  { id: 3, nombre: 'Kit de Arrastre', precio: 180000, categoria: 'Transmisión', imagen: '⚙️' },
  { id: 4, nombre: 'Pastillas de Freno', precio: 65000, categoria: 'Frenos', imagen: '🛑' },
  { id: 5, nombre: 'Llanta Trasera 140/70', precio: 280000, categoria: 'Llantas', imagen: '🔘' },
  { id: 6, nombre: 'Batería 12V 9Ah', precio: 120000, categoria: 'Eléctrico', imagen: '🔋' },
  { id: 7, nombre: 'Escape Deportivo', precio: 450000, categoria: 'Performance', imagen: '💨' },
  { id: 8, nombre: 'Guantes de Cuero', precio: 85000, categoria: 'Seguridad', imagen: '🧤' }
];

function Productos({ navegar, agregarAlCarrito }) {
  const [filtro, setFiltro] = useState('Todos');
  const [mensaje, setMensaje] = useState(null);

  const categorias = ['Todos', ...new Set(productosData.map(p => p.categoria))];
  const productosFiltrados = filtro === 'Todos' ? productosData : productosData.filter(p => p.categoria === filtro);

  const handleAgregar = (producto) => {
    agregarAlCarrito(producto);
    setMensaje(`${producto.nombre} agregado`);
    setTimeout(() => setMensaje(null), 3000);
  };

  const formatearPrecio = (precio) => {
    return new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(precio);
  };

  const styles = {
    container: { maxWidth: '1200px', margin: '0 auto', padding: '40px 20px' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '30px', marginTop: '30px' },
    card: { backgroundColor: 'white', borderRadius: '15px', overflow: 'hidden', boxShadow: '0 10px 30px rgba(0,0,0,0.1)', textAlign: 'center' },
    filtros: { display: 'flex', gap: '10px', justifyContent: 'center', flexWrap: 'wrap', marginBottom: '30px' }
  };

  return (
    <div style={styles.container}>
      <h1 style={{textAlign: 'center', fontSize: '36px', marginBottom: '30px'}}>🛒 Nuestros Productos</h1>
      
      <div style={styles.filtros}>
        {categorias.map(cat => (
          <button key={cat} onClick={() => setFiltro(cat)} style={{
            padding: '10px 20px',
            border: '2px solid #ff6b00',
            backgroundColor: filtro === cat ? '#ff6b00' : 'white',
            color: filtro === cat ? 'white' : '#ff6b00',
            borderRadius: '25px',
            cursor: 'pointer',
            fontWeight: '600'
          }}>{cat}</button>
        ))}
      </div>

      <div style={styles.grid}>
        {productosFiltrados.map(prod => (
          <div key={prod.id} style={styles.card}>
            <div style={{fontSize: '80px', padding: '30px', backgroundColor: '#f7fafc'}}>{prod.imagen}</div>
            <div style={{padding: '25px'}}>
              <div style={{fontSize: '12px', color: '#ff6b00', fontWeight: '700', textTransform: 'uppercase'}}>{prod.categoria}</div>
              <h3 style={{fontSize: '18px', margin: '10px 0'}}>{prod.nombre}</h3>
              <div style={{fontSize: '24px', fontWeight: '800', color: '#ff6b00', margin: '15px 0'}}>{formatearPrecio(prod.precio)}</div>
              <button onClick={() => handleAgregar(prod)} style={{
                width: '100%',
                padding: '12px',
                backgroundColor: '#ff6b00',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                fontWeight: '700',
                cursor: 'pointer'
              }}>🛒 Agregar</button>
            </div>
          </div>
        ))}
      </div>

      {mensaje && (
        <div style={{position: 'fixed', bottom: '30px', right: '30px', backgroundColor: '#c6f6d5', color: '#22543d', padding: '15px 25px', borderRadius: '10px', boxShadow: '0 4px 15px rgba(0,0,0,0.2)'}}>
          ✓ {mensaje}
        </div>
      )}
    </div>
  );
}

export default Productos;
